// VERIFY SIGNATURE — rejette les requêtes sans le header X-Pessobot-Signature
// ⚠️ n8n Cloud Starter/Pro : secret hardcodé (pas de $env disponible).
const expected = '607dd413213a97fe2a54f9ebdab7341596d603640bb093ae';
const webhook = $('Webhook PessoBot').first().json;
const received = (webhook.headers && (webhook.headers['x-pessobot-signature'] || webhook.headers['X-Pessobot-Signature'])) || '';
if (expected && received !== expected) {
  throw new Error('Unauthorized: invalid or missing X-Pessobot-Signature header');
}
return [{ json: webhook }];

// Build 429 message : reformule la raison technique en message utilisateur chaleureux.
const r = $input.first().json;
const retry = Number(r.retry_after_seconds) || 10;
const reason = r.reason || 'Pause technique';
let userMsg;
if (reason.startsWith('Rafale')) {
  userMsg = `Houla, ${retry} s de pause — je te réponds juste après 🙏`;
} else if (reason.startsWith('Trop')) {
  userMsg = `On fait beaucoup d'échanges depuis ton IP (limite 30 / 10 min). Reviens dans ~${Math.ceil(retry / 60)} min, je garderai le fil de notre conversation.`;
} else {
  userMsg = `Petit temps de pause côté serveur, ré-essaie dans ${retry} s.`;
}
return [{ json: { response: userMsg, rate_limited: true, retry_after_seconds: retry } }];

// ────────────────────────────────────────────────────────────────────────────
// BUILD SYSTEM PROMPT (v3 — persona courte + tool calling)
// Gain tokens : ~900 → ~400 (le menu n'est plus injecté, l'agent appelle
// get_menu(category?) à la demande).
// ────────────────────────────────────────────────────────────────────────────

// 1. Webhook
const webhook = $('Webhook PessoBot').first().json;
const userMsg = (webhook.body && webhook.body.message) || '';
const sessionId = (webhook.body && webhook.body.sessionid) || 'session-inconnue';
const userId = (webhook.body && webhook.body.userId) || null;

// 2. Profile snapshot + bar (requête combinée — optim v3.1)
let snap = {};
let bar = { address: {}, hours: [], contact: {}, subscription_info: {} };
try {
  const rows = $('Get Profile + Bar').all();
  if (rows[0] && rows[0].json) {
    snap = rows[0].json.profile || {};
    if (rows[0].json.bar) bar = rows[0].json.bar;
  }
} catch (e) {}

// Connexion = JWT côté app : dès que userId est envoyé, l'utilisateur n'est plus visiteur.
// (L'ancienne règle exigeait snap.first_name — faux négatif si prénom vide en BDD.)
const firstName =
  (snap.first_name && String(snap.first_name).trim()) ||
  (webhook.body && webhook.body.first_name && String(webhook.body.first_name).trim()) ||
  'Membre';
const isConnected = Boolean(userId);
const plan = (snap.plan || (webhook.body && webhook.body.subscription_tier) || 'free').toLowerCase();
const isOraPlus = ['ora_plus', 'starter', 'premium', 'vip'].includes(plan);
const totalOrders = snap.total_orders || 0;
const isRegular = isConnected && totalOrders >= 3;

let clientStatus = 'VISITOR';
if (isConnected) clientStatus = isOraPlus ? 'VIP_MEMBER' : 'FREE_MEMBER';

// Signaux perso (compact JSON pour le prompt)
const personalSignals = {};
if (snap.favorite_product) personalSignals.favorite = snap.favorite_product;
if (snap.upcoming_event) personalSignals.upcoming_event = snap.upcoming_event;
if (snap.upcoming_bilan) personalSignals.upcoming_bilan = snap.upcoming_bilan;
if (totalOrders) personalSignals.total_orders = totalOrders;

// 3. Bar settings (déjà chargés en étape 2 via la requête combinée)
const addressLine = (bar.address && bar.address.full) || '(non renseignée)';
const hoursCompact = Array.isArray(bar.hours)
  ? bar.hours.map(h => `${h.label} ${h.value}`).join(' | ')
  : '(non renseignées)';
const contact = bar.contact || {};
const contactLine = [contact.email, contact.phone, contact.instagram].filter(Boolean).join(' · ') || '(non renseigné)';

// Óra+ compact
const oraPlus = (bar.subscription_info && bar.subscription_info.ora_plus) || null;
const oraPlusJson = oraPlus ? JSON.stringify({
  name: oraPlus.name,
  tagline: oraPlus.tagline,
  price: oraPlus.price,
  period: oraPlus.period,
  highlight: oraPlus.highlight,
  benefits: oraPlus.benefits,
  cta_url: oraPlus.cta_url,
}) : 'null';

// 4. Closing tactique — mentions Óra+ intelligentes (1 fois par conversation, sur signal)
// SIGNAL = contexte qui rend la mention naturelle et utile, pas forcée.
// Signaux valables : l'utilisateur demande un prix, compare plusieurs produits, mentionne qu'il vient souvent, commande plusieurs boissons, demande "c'est abordable ?", ou a un historique élevé.
// INTERDIT : mentionner Óra+ en réponse à une question coaching, en opener, ou si déjà glissé dans ce fil.
let closing;
if (clientStatus === 'VISITOR') {
  closing = 'Conseille naturellement. Si la conversation se conclut, rappelle qu\'il faut un compte pour commander. Pas de mention Óra+ ni de paiement.';
} else if (clientStatus === 'FREE_MEMBER' && isRegular && oraPlus) {
  closing = `${firstName} commande régulièrement (${totalOrders} fois). Tu peux mentionner Óra+ UNE FOIS par conversation, mais seulement quand un signal prix ou fréquence apparaît naturellement (ex : ${firstName} demande le prix, compare des boissons, ou commande plusieurs produits). Formule courte, ton léger : "Au passage, avec ${oraPlus.name} (${oraPlus.highlight}) tu ferais des économies à chaque passage 😊 [En savoir plus](${oraPlus.cta_url})". Puis n\'y reviens plus.`;
} else if (clientStatus === 'FREE_MEMBER' && oraPlus) {
  closing = `Conseille simplement. Si un signal prix ou valeur apparaît (${firstName} demande un prix, s\'étonne du tarif, commande plusieurs boissons), tu peux glisser Óra+ UNE SEULE FOIS en 1 phrase : "Avec ${oraPlus.name}, ce serait moins cher (${oraPlus.highlight}) — [voir l\'abonnement](${oraPlus.cta_url})". Jamais sans ce signal, jamais deux fois.`;
} else if (clientStatus === 'VIP_MEMBER') {
  closing = `${firstName} est déjà abonné(e) ${oraPlus ? oraPlus.name : 'Óra+'}. Confirme simplement. Pas d\'upsell.`;
} else {
  closing = 'Conseille simplement, pas d\'upsell.';
}

// 5. Persona v3 (compacte, ~400 tokens vs ~900 en v2.1)
const who = isConnected ? firstName : 'un visiteur anonyme';
const personalJson = Object.keys(personalSignals).length ? JSON.stringify(personalSignals) : 'null';

const systemPrompt = `Tu es PessoBot, assistant bar & boissons de PessÓra (Martinique).

RÈGLES ABSOLUES :
1. JAMAIS d'info bar/menu/abonnement inventée — uniquement depuis les données fournies ou les tools.
2. MENU / BOISSONS — OBLIGATION : avant de citer des noms de produits, des prix, des kcal ou des ingrédients, tu appelles get_menu (sans argument = carte complète ; ou category = wellness | energie | shakes | coffee). Tu n'écris QUE ce qui figure dans items[] du tool : name, price, calories, protein, pitch, ingredients, benefits. Copie chaque name tel quel (ex. DETOX MY BODY, SPICY MANGO, PINK DRAGON). INTERDIT : inventer des « produits » génériques (Immunité, Détox, Focus, Pré-workout comme titre), des listes d'ingrédients fictives, ou des prix (ex. 6,50 €, 7 €) absents du JSON.
3. Si get_menu renvoie items vide ou échoue : ne fabrique PAS une carte de toutes pièces. Dis que tu n'as pas la carte synchronisée et renvoie vers [Menu](/menu).
4. Si tu ne sais pas : dis-le ("je n'ai pas cette info à jour").
5. Conseil sur une boisson : cite UNIQUEMENT pitch / ingredients / benefits du JSON get_menu — pas de fiche nutrition « type smoothie bar » inventée.
6. Tu parles à ${who} (${clientStatus}${isConnected ? `, plan=${plan}` : ''}). Reste court, chaleureux, précis.
7. Pas de titres markdown lourds. Pour les liens, utilise TOUJOURS [libellé](URL) (ils sont cliquables côté app).
8. Utilise les signaux perso avec tact, jamais listés brut.
9. TU N'ES PAS UN COACH. Ton rôle : orienter sur les boissons du bar, les horaires, l'abonnement Óra+. RIEN D'AUTRE.
   Dès que la conversation dérive vers du coaching personnel — plan alimentaire, programme de perte de poids, suivi d'objectifs santé, "que dois-je manger", "combien de calories par jour", "aide-moi à progresser", "fais-moi un programme", "régime", "maigrir", "mincir", "suivi nutrition" — réponds en 1 seule phrase et renvoie vers le bilan : "Mon rôle s'arrête aux boissons du bar 😊 Pour un accompagnement personnalisé, le [Bilan Bien-Être](/bilan-bien-etre) est fait pour toi !"
   UNE question de ciblage boisson ("tu fais du sport ce matin ?", "plutôt sucré ou fruité ?") reste dans mon rôle. Enchaîner les questions comme un coach est INTERDIT.

MÉTHODE :
- Question sur le menu / goûts / prix / « qu'avez-vous » → appelle get_menu EN PREMIER, puis réponds en listant les name réels par catégorie.
- Demande vague hors menu → UNE question de ciblage.
- Demande précise → réponse appuyée sur les données du tool.

TOOLS (tu n'as PAS le menu en mémoire — passage obligatoire par l'outil) :
- get_menu(category?) — OBLIGATOIRE pour toute réponse sur la carte, les boissons, les tarifs, les conseils par gamme. Sans argument = tout le catalogue. Ne décris jamais le menu sans avoir reçu items[] de cet outil dans ce tour.
- get_upcoming_events(limit?) — événements publics à venir. OBLIGATOIRE si événements, ateliers, dates.

INFOS BAR (pré-chargées) :
- Adresse : ${addressLine}
- Horaires : ${hoursCompact}
- Contact : ${contactLine}

PROFIL UTILISATEUR (JSON compact) : ${personalJson}
ABONNEMENT ÓRA+ (JSON, à citer tel quel) : ${oraPlusJson}

CLOSING :
${closing}`;

return [{ json: { systemPrompt, userMessage: userMsg, sessionId } }];

// Nettoyage léger du markdown retourné par l'agent :
// - on retire les titres markdown (# / ##) qui n'ont pas leur place dans une bulle de chat
// - on convertit les puces '- ' / '• ' en '👉 ' (cohérent avec la persona)
// - on supprime les séparateurs '---' / '***' (bruit visuel)
// On LAISSE passer **bold** et *italic* : le front les rend en <strong>/<em>.
let rawText = $input.first().json.output || '';
let cleanText = rawText
  .replace(/^[#]+\s+/gm, '')
  .replace(/^[-\u2022]\s+/gm, '👉 ')
  .replace(/^\s*-{3,}\s*$/gm, '')
  .trim();
return [{ json: { response: cleanText } }];
